{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.MYNTRA_SJIT_MASTER as WITH sjit_inv_metadata AS ( SELECT sku_group, category, title, material_new, print_design, fit, sleeve_type, collar_new FROM snitch_db.maplemonk.Myntra_SJIT_INV_report QUALIFY ROW_NUMBER() OVER(PARTITION BY sku_group ORDER BY date DESC) = 1 ), color_data AS ( SELECT sku_group, COLOR FROM snitch_db.maplemonk.metafields_data QUALIFY ROW_NUMBER() OVER(PARTITION BY sku_group ORDER BY status DESC) = 1 ), inward_data AS ( SELECT SKU_GROUP, MIN(DATE) AS first_inward_date, SUM(opening_inventory) AS opening_inventory FROM snitch_db.maplemonk.Myntra_SJIT_INV_report GROUP BY SKU_GROUP ), sales_after_inward AS ( SELECT k.SKU_GROUP, i.first_inward_date, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 7, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_7, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 15, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_15, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 30, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_30 FROM snitch_db.maplemonk.Myntra_Sjit_fact_item k JOIN inward_data i ON k.SKU_GROUP = i.SKU_GROUP GROUP BY k.SKU_GROUP, i.first_inward_date ), str_data AS ( SELECT s.SKU_GROUP, i.opening_inventory, DIV0(s.sales_day_7, i.opening_inventory) AS STR_DAY_7, DIV0(s.sales_day_15, i.opening_inventory) AS STR_DAY_15, DIV0(s.sales_day_30, i.opening_inventory) AS STR_DAY_30 FROM sales_after_inward s JOIN inward_data i ON s.SKU_GROUP = i.SKU_GROUP ), sku_group_data AS ( SELECT sku_group, order_date, SUM(TOTAL_QUANTITY) AS suborder_quantity, SUM(return_quantity) AS return_quantity, MAX(MRP) AS mrp, SUM(SP) AS SP FROM snitch_db.maplemonk.Myntra_Sjit_fact_item GROUP BY 1, 2 ), first_order_dates AS ( SELECT sku_group, MIN(order_date) AS first_order_date, MAX(order_date) AS last_order_date, DATEDIFF(\'DAY\', MIN(order_date), CURRENT_DATE) AS days_since_first_order, DATEDIFF(\'DAY\', MAX(order_date), CURRENT_DATE) AS days_since_last_order, DATEDIFF(\'DAY\', MIN(order_date), MAX(order_date)) AS total_days_sold FROM sku_group_data GROUP BY sku_group ), total_sales AS ( SELECT sgd.sku_group, fod.first_order_date, fod.last_order_date, fod.days_since_first_order, fod.days_since_last_order, fod.total_days_sold, MAX(mrp) AS MRP, DIV0(SUM(SP), SUM(suborder_quantity)) AS ASP, SUM(return_quantity) AS total_returns, SUM(suborder_quantity) AS total_sales, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 30, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_30_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 15, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_15_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 7, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_7_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 90, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_90_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 60, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_60_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 180, fod.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_180_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 30 THEN suborder_quantity ELSE 0 END) AS sales_last_30_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 15 THEN suborder_quantity ELSE 0 END) AS sales_last_15_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 7 THEN suborder_quantity ELSE 0 END) AS sales_last_7_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 60 THEN suborder_quantity ELSE 0 END) AS sales_last_60_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 90 THEN suborder_quantity ELSE 0 END) AS sales_last_90_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 180 THEN suborder_quantity ELSE 0 END) AS sales_last_180_days, CASE WHEN fod.total_days_sold = 0 THEN SUM(suborder_quantity) ELSE DIV0(SUM(suborder_quantity), fod.total_days_sold) END AS natural_ros FROM sku_group_data sgd INNER JOIN first_order_dates fod ON sgd.sku_group = fod.sku_group GROUP BY sgd.sku_group, fod.first_order_date, fod.last_order_date, fod.days_since_first_order, fod.days_since_last_order, fod.total_days_sold ), enhanced_total_sales AS ( SELECT *, GREATEST(DIV0(sales_first_30_days, 30), DIV0(sales_last_30_days, 30), natural_ros) AS max_first_30_last_30_natural_ros, GREATEST(DIV0(sales_first_30_days, 30), DIV0(sales_last_30_days, 30), natural_ros, DIV0(sales_first_7_days, 7)) AS max_first_30_last_30_natural_ros_first_7_days, CASE WHEN total_sales = 0 THEN 0 ELSE (total_returns / total_sales) * 100 END AS average_return_since_first_order, CASE WHEN max_first_30_last_30_natural_ros > 5 THEN max_first_30_last_30_natural_ros WHEN max_first_30_last_30_natural_ros < 5 AND max_first_30_last_30_natural_ros_first_7_days > 10 THEN max_first_30_last_30_natural_ros_first_7_days WHEN total_sales > 800 THEN GREATEST(natural_ros, DIV0(sales_last_7_days, 7)) ELSE natural_ros END AS final_ros FROM total_sales ), PivotTable AS ( WITH latest_inventory_date AS ( SELECT MAX(date) AS max_date FROM snitch_db.maplemonk.Myntra_SJIT_INV_report ) SELECT sku_group, GREATEST(SUM(closing_inventory), 0) AS Sellable_Inventory, SUM(CASE WHEN SIZE = \'XS\' OR SIZE = \'28\' THEN closing_inventory ELSE 0 END) AS XS_units, SUM(CASE WHEN SIZE = \'S\' OR SIZE = \'30\' THEN closing_inventory ELSE 0 END) AS S_units, SUM(CASE WHEN SIZE = \'M\' OR SIZE = \'32\' THEN closing_inventory ELSE 0 END) AS M_units, SUM(CASE WHEN SIZE = \'L\' OR SIZE = \'34\' THEN closing_inventory ELSE 0 END) AS L_units, SUM(CASE WHEN SIZE = \'XL\' OR SIZE = \'36\' THEN closing_inventory ELSE 0 END) AS XL_units, SUM(CASE WHEN SIZE IN (\'XXL\', \'2XL\', \'38\') THEN closing_inventory ELSE 0 END) AS XXL_units, SUM(CASE WHEN SIZE = \'3XL\' OR SIZE = \'40\' THEN closing_inventory ELSE 0 END) AS XL3_units, SUM(CASE WHEN SIZE = \'4XL\' OR SIZE = \'42\' THEN closing_inventory ELSE 0 END) AS XL4_units, SUM(CASE WHEN SIZE = \'5XL\' OR SIZE = \'44\' THEN closing_inventory ELSE 0 END) AS XL5_units, SUM(CASE WHEN SIZE = \'6XL\' OR SIZE = \'46\' THEN closing_inventory ELSE 0 END) AS XL6_units, SUM(CASE WHEN SIZE = \'7XL\' OR SIZE = \'48\' THEN closing_inventory ELSE 0 END) AS XL7_units, SUM(CASE WHEN SIZE = \'8XL\' OR SIZE = \'50\' THEN closing_inventory ELSE 0 END) AS XL8_units, SUM(CASE WHEN SIZE IS NULL THEN closing_inventory ELSE 0 END) AS NA_units, COUNT(DISTINCT CASE WHEN closing_inventory > 0 THEN SIZE ELSE NULL END) AS num_size_available FROM snitch_db.maplemonk.Myntra_SJIT_INV_report WHERE date = (SELECT max_date FROM latest_inventory_date) GROUP BY sku_group ), availability_master_v2 AS ( SELECT * FROM snitch_db.maplemonk.availability_master_v2 ), category_pareto AS ( SELECT e.sku_group, meta.category, e.total_sales, SUM(e.total_sales) OVER (PARTITION BY meta.category) AS category_total_sales, SUM(e.total_sales) OVER ( PARTITION BY meta.category ORDER BY e.total_sales DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_sales FROM enhanced_total_sales e LEFT JOIN sjit_inv_metadata meta ON e.sku_group = meta.sku_group ), category_pareto_final AS ( SELECT *, DIV0(cumulative_sales, category_total_sales) * 100 AS cumulative_sales_pct, CASE WHEN DIV0(cumulative_sales, category_total_sales) * 100 <= 40 THEN \'Top 40%\' WHEN DIV0(cumulative_sales, category_total_sales) * 100 <= 80 THEN \'40-80%\' ELSE \'Bottom 20%\' END AS pareto_segment FROM category_pareto ) SELECT COALESCE(a.sku_group, b.sku_group) AS sku_group, a.first_order_date, a.last_order_date, a.days_since_first_order, a.days_since_last_order, a.total_days_sold, a.MRP, a.ASP, a.total_returns, a.total_sales, a.sales_first_30_days, a.sales_first_15_days, a.sales_first_7_days, a.sales_first_90_days, a.sales_first_60_days, a.sales_first_180_days, a.sales_last_30_days, a.sales_last_15_days, a.sales_last_7_days, a.sales_last_60_days, a.sales_last_90_days, a.sales_last_180_days, a.natural_ros, a.max_first_30_last_30_natural_ros, a.max_first_30_last_30_natural_ros_first_7_days, a.average_return_since_first_order, a.final_ros, d.opening_inventory, d.STR_DAY_7, d.STR_DAY_15, d.STR_DAY_30, b.SELLABLE_INVENTORY, b.XS_UNITS, b.S_UNITS, b.M_UNITS, b.L_UNITS, b.XL_UNITS, b.XXL_UNITS, b.XL3_UNITS, b.XL4_UNITS, b.XL5_UNITS, b.XL6_UNITS, b.XL7_UNITS, b.XL8_UNITS, b.NA_UNITS, b.num_size_available, CASE WHEN (CASE WHEN b.M_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN b.L_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN b.XL_units > 0 THEN 1 ELSE 0 END) < 3 THEN \'Cut Size\' ELSE \'Full Size\' END AS Cute_Size_Fag, DIV0((a.TOTAL_SALES - a.TOTAL_RETURNS), (a.TOTAL_SALES - a.TOTAL_RETURNS + B.SELLABLE_INVENTORY)) * 100 AS Sell_through, DIV0(B.SELLABLE_INVENTORY, (DIV0(a.SALES_LAST_30_DAYS, 30))) AS DOI, m.title, m.category, c.PRODUCT_NAME, c.SKU_CLASS, m.PRINT_DESIGN, m.COLLAR_NEW, m.MATERIAL_NEW, m.FIT, cd.COLOR, m.SLEEVE_TYPE, cpf.cumulative_sales_pct, cpf.pareto_segment, c.SELLABLE_INVENTORY AS warehouse_inventory, c.XS_UNITS AS warehouse_XS_UNITS, c.S_UNITS AS warehouse_S_UNITS, c.M_UNITS AS warehouse_M_UNITS, c.L_UNITS AS warehouse_L_UNITS, c.XL_UNITS AS warehouse_XL_UNITS, c.XXL_UNITS AS warehouse_XXL_UNITS FROM enhanced_total_sales a FULL OUTER JOIN PivotTable b ON a.sku_group = b.sku_group LEFT JOIN str_data d ON COALESCE(a.sku_group, b.sku_group) = d.sku_group LEFT JOIN availability_master_v2 c ON COALESCE(a.sku_group, b.sku_group) = c.sku_group LEFT JOIN sjit_inv_metadata m ON COALESCE(a.sku_group, b.sku_group) = m.sku_group LEFT JOIN color_data cd ON COALESCE(a.sku_group, b.sku_group) = cd.sku_group LEFT JOIN category_pareto_final cpf ON COALESCE(a.sku_group, b.sku_group) = cpf.sku_group ORDER BY a.total_sales DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            